// Abstract bank accounts
public class Q08 {abstract static class BankAccount {double balance;BankAccount(double b){balance=b;}abstract void deposit(double x);abstract void withdraw(double x);} static class SavingsAccount extends BankAccount {SavingsAccount(double b){super(b);}void deposit(double x){if(x>0)balance+=x;}void withdraw(double x){if(x>0&&balance-x>=100)balance-=x;else System.out.println("Savings withdrawal denied");}} static class CurrentAccount extends BankAccount {CurrentAccount(double b){super(b);}void deposit(double x){if(x>0)balance+=x;}void withdraw(double x){if(x>0&&x<=balance)balance-=x;else System.out.println("Current withdrawal denied");}}public static void main(String[] args){BankAccount s=new SavingsAccount(500),c=new CurrentAccount(500);s.deposit(200);s.withdraw(250);c.withdraw(450);System.out.println("Savings: "+s.balance+", Current: "+c.balance);}}
